mapper.insert:
insert into public_agent_config_rollout_targets(
    target_id, rollout_id, user_id, linux_server_id, container_id, port,
    process_pid, process_started_at, base_url,
    status, retry_count, next_retry_at, lease_until, lease_token, force_stop, created_at, updated_at
) values (
    #{row.targetId}, #{row.rolloutId}, #{row.userId}, #{row.linuxServerId}, #{row.containerId},
    #{row.port}, #{row.processPid}, #{row.processStartedAt}, #{row.baseUrl},
    'RETRY_WAIT', #{row.retryCount}, #{now}, null, null,
    exists (
        select 1
        from public_agent_config_rollouts replacement
        join public_agent_config_rollout_targets previous
          on previous.rollout_id = replacement.supersedes_rollout_id
        where replacement.rollout_id = #{row.rolloutId}
          and previous.status = 'ABANDONED'
          and previous.last_error = 'ROLLOUT_SUPERSEDED'
          and previous.user_id = #{row.userId}
          and previous.linux_server_id = #{row.linuxServerId}
          and previous.container_id = #{row.containerId}
          and previous.port = #{row.port}
          and previous.process_pid = #{row.processPid}
          and previous.process_started_at = #{row.processStartedAt}
    ),
    #{now}, #{now}
) on conflict (rollout_id, linux_server_id, container_id, port) do nothing

